-- Source allocation and operational lifecycle. No old document is posted by this migration.
ALTER TABLE document_drafts ADD COLUMN deleted_at TEXT;
ALTER TABLE document_drafts ADD COLUMN operation_state TEXT NOT NULL DEFAULT '';
CREATE TABLE stock_buckets(part_id TEXT NOT NULL REFERENCES parts(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),stock_state TEXT NOT NULL CHECK(stock_state IN ('new','recovered','pending_scrap')),quantity_milli INTEGER NOT NULL CHECK(typeof(quantity_milli)='integer' AND quantity_milli>=0 AND quantity_milli<=9000000000000000),value_vnd INTEGER NOT NULL CHECK(typeof(value_vnd)='integer' AND value_vnd>=0 AND value_vnd<=9000000000000000),version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(part_id,warehouse_id,stock_state));
CREATE TABLE stock_lots(source_line_id TEXT PRIMARY KEY REFERENCES inventory_document_lines(id),part_id TEXT NOT NULL REFERENCES parts(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),stock_state TEXT NOT NULL CHECK(stock_state IN ('new','recovered','pending_scrap')),initial_quantity_milli INTEGER NOT NULL CHECK(initial_quantity_milli>0),remaining_quantity_milli INTEGER NOT NULL CHECK(remaining_quantity_milli>=0 AND remaining_quantity_milli<=initial_quantity_milli),original_value_vnd INTEGER NOT NULL CHECK(original_value_vnd>=0),available_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX idx_lots_available ON stock_lots(part_id,warehouse_id,stock_state,available_at,source_line_id);
CREATE TABLE stock_source_allocations(consumer_line_id TEXT NOT NULL REFERENCES inventory_document_lines(id),source_line_id TEXT NOT NULL REFERENCES inventory_document_lines(id),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),PRIMARY KEY(consumer_line_id,source_line_id));
CREATE INDEX idx_alloc_source ON stock_source_allocations(source_line_id,consumer_line_id);
CREATE TABLE stock_cost_dependencies(consumer_line_id TEXT NOT NULL REFERENCES inventory_document_lines(id),source_line_id TEXT NOT NULL REFERENCES inventory_document_lines(id),PRIMARY KEY(consumer_line_id,source_line_id));
CREATE INDEX idx_cost_source ON stock_cost_dependencies(source_line_id,consumer_line_id);
INSERT INTO stock_lots SELECT l.id,l.part_id,l.to_warehouse_id,'new',l.quantity_milli,l.quantity_milli,l.amount_vnd,coalesce((SELECT business_at FROM document_drafts WHERE posted_inventory_id=d.id),d.business_date||'T00:00'),1 FROM inventory_document_lines l JOIN inventory_documents d ON d.id=l.document_id WHERE d.status='posted' AND d.type='IN';
INSERT INTO stock_buckets SELECT part_id,warehouse_id,'new',quantity_milli,value_vnd,1 FROM stock_balances;
CREATE TABLE stock_usages(id TEXT PRIMARY KEY,root_line_id TEXT NOT NULL REFERENCES inventory_document_lines(id),document_id TEXT NOT NULL REFERENCES inventory_documents(id),parent_usage_id TEXT REFERENCES stock_usages(id),part_id TEXT NOT NULL REFERENCES parts(id),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),open_quantity_milli INTEGER NOT NULL CHECK(open_quantity_milli>=0 AND open_quantity_milli<=quantity_milli),open_value_vnd INTEGER NOT NULL CHECK(open_value_vnd>=0),target_type TEXT NOT NULL,target_id TEXT NOT NULL,position TEXT NOT NULL DEFAULT '',started_at TEXT NOT NULL,odo_milli INTEGER,hours_milli INTEGER,version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX idx_usage_part ON stock_usages(part_id,open_quantity_milli);
CREATE TABLE usage_serials(usage_id TEXT NOT NULL REFERENCES stock_usages(id),part_id TEXT NOT NULL REFERENCES parts(id),serial_key TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)),PRIMARY KEY(usage_id,part_id,serial_key));
CREATE UNIQUE INDEX idx_active_usage_serial ON usage_serials(part_id,serial_key) WHERE active=1;
CREATE TABLE equipment_operations(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES inventory_documents(id),from_usage_id TEXT NOT NULL REFERENCES stock_usages(id),to_usage_id TEXT NOT NULL REFERENCES stock_usages(id),quantity_milli INTEGER NOT NULL,from_position TEXT NOT NULL,to_position TEXT NOT NULL,effective_at TEXT NOT NULL);
CREATE TABLE retread_jobs(document_id TEXT NOT NULL REFERENCES document_drafts(id),send_line_id TEXT PRIMARY KEY REFERENCES inventory_document_lines(id),part_id TEXT NOT NULL REFERENCES parts(id),serial_before TEXT NOT NULL,source_value_vnd INTEGER NOT NULL CHECK(source_value_vnd>=0),stage TEXT NOT NULL CHECK(stage IN ('sent','received')),received_inventory_id TEXT REFERENCES inventory_documents(id),received_line_id TEXT REFERENCES inventory_document_lines(id),serial_after TEXT,repair_cost_vnd INTEGER,received_at TEXT);
CREATE TABLE opening_groups(part_id TEXT NOT NULL REFERENCES parts(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),stock_state TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES inventory_documents(id),start_at TEXT NOT NULL,PRIMARY KEY(part_id,warehouse_id,stock_state));
CREATE TRIGGER opening_no_prior_stock BEFORE INSERT ON opening_groups WHEN EXISTS(SELECT 1 FROM inventory_document_lines l JOIN inventory_documents d ON d.id=l.document_id WHERE l.part_id=NEW.part_id AND (l.to_warehouse_id=NEW.warehouse_id OR l.from_warehouse_id=NEW.warehouse_id) AND d.status='posted' AND d.id<>NEW.document_id) BEGIN SELECT RAISE(ABORT,'OPENING_HAS_HISTORY'); END;
CREATE TABLE receipt_mutation_locks(document_id TEXT PRIMARY KEY REFERENCES document_drafts(id),expected_version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES app_users(id),mode TEXT NOT NULL CHECK(mode IN ('edit','delete','receive')));
CREATE TRIGGER receipt_mutation_version BEFORE INSERT ON receipt_mutation_locks WHEN NOT EXISTS(SELECT 1 FROM document_drafts WHERE id=NEW.document_id AND version=NEW.expected_version AND posted_inventory_id IS NOT NULL AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'RECEIPT_VERSION_CONFLICT'); END;
CREATE TRIGGER receipt_mutation_period BEFORE INSERT ON receipt_mutation_locks WHEN NEW.mode<>'receive' AND (SELECT substr(business_at,1,7) FROM document_drafts WHERE id=NEW.document_id)<=(SELECT max(period) FROM accounting_periods WHERE is_locked=1) BEGIN SELECT RAISE(ABORT,'RECEIPT_PERIOD_LOCKED'); END;
CREATE TRIGGER receipt_mutation_dependencies BEFORE INSERT ON receipt_mutation_locks WHEN NEW.mode<>'receive' AND (
 EXISTS(SELECT 1 FROM stock_source_allocations a JOIN inventory_document_lines l ON l.id=a.source_line_id JOIN document_drafts d ON d.posted_inventory_id=l.document_id WHERE d.id=NEW.document_id)
 OR EXISTS(SELECT 1 FROM stock_cost_dependencies a JOIN inventory_document_lines l ON l.id=a.source_line_id JOIN document_drafts d ON d.posted_inventory_id=l.document_id WHERE d.id=NEW.document_id)
 OR EXISTS(SELECT 1 FROM inventory_document_lines l JOIN document_drafts d ON d.posted_inventory_id=l.document_id LEFT JOIN stock_lots s ON s.source_line_id=l.id WHERE d.id=NEW.document_id AND (s.source_line_id IS NULL OR s.remaining_quantity_milli<>s.initial_quantity_milli))
 OR EXISTS(SELECT 1 FROM document_draft_lines x JOIN inventory_document_lines l ON l.id=json_extract(x.line_json,'$.source_line_id') JOIN document_drafts d ON d.posted_inventory_id=l.document_id JOIN document_drafts other ON other.id=x.document_id WHERE d.id=NEW.document_id AND other.id<>d.id AND other.status<>'cancelled' AND other.deleted_at IS NULL)
) BEGIN SELECT RAISE(ABORT,'RECEIPT_HAS_DEPENDENCIES'); END;
DROP TRIGGER posted_prepared_update;
DROP TRIGGER posted_prepared_delete;
CREATE TRIGGER posted_prepared_update BEFORE UPDATE ON document_drafts WHEN OLD.posted_inventory_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=OLD.id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
CREATE TRIGGER posted_prepared_delete BEFORE DELETE ON document_drafts WHEN OLD.posted_inventory_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_lines_insert;
CREATE TRIGGER posted_document_draft_lines_insert BEFORE INSERT ON document_draft_lines WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=NEW.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=NEW.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_lines_update;
CREATE TRIGGER posted_document_draft_lines_update BEFORE UPDATE ON document_draft_lines WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=OLD.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=OLD.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_lines_delete;
CREATE TRIGGER posted_document_draft_lines_delete BEFORE DELETE ON document_draft_lines WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=OLD.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=OLD.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_serials_insert;
CREATE TRIGGER posted_document_draft_serials_insert BEFORE INSERT ON document_draft_serials WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=NEW.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=NEW.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_serials_update;
CREATE TRIGGER posted_document_draft_serials_update BEFORE UPDATE ON document_draft_serials WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=OLD.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=OLD.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
DROP TRIGGER posted_document_draft_serials_delete;
CREATE TRIGGER posted_document_draft_serials_delete BEFORE DELETE ON document_draft_serials WHEN (SELECT posted_inventory_id FROM document_drafts WHERE id=OLD.document_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM receipt_mutation_locks WHERE document_id=OLD.document_id) BEGIN SELECT RAISE(ABORT,'POSTED_DOCUMENT_IMMUTABLE'); END;
CREATE TRIGGER posted_receipt_update_locked BEFORE UPDATE ON inventory_documents WHEN NEW.status='posted' AND substr(NEW.business_date,1,7)<=(SELECT max(period) FROM accounting_periods WHERE is_locked=1) BEGIN SELECT RAISE(ABORT,'RECEIPT_PERIOD_LOCKED'); END;
